export type Subject = 'math' | 'reading';
export type Skill = { id:string; grade:number; subject:Subject; domain:string; title:string; kind:string; p:any; objective:string; teach:string; order:number; prerequisite?:string;language?:Locale };
export type Question = { id:string; prompt:string; answer:string; choices:string[]; hint:string; explanation:string; visual?:any; passage?:string; tiles?:string[]; word?:string; listeningText?:string; tileJoin?:string; repeated?:boolean;canonicalKey?:string;canonicalContentId?:string;language?:Locale };
type Row = [string,string,any?];
const skills:Skill[]=[];
function group(grade:number, subject:Subject, domain:string, rows:Row[]) { rows.forEach(([title,kind,p={}])=>{const previous=skills.filter(s=>s.grade===grade&&s.subject===subject&&s.domain===domain).at(-1);skills.push({id:`${subject[0]}${grade}-${skills.filter(s=>s.grade===grade&&s.subject===subject).length+1}`,grade,subject,domain,title,kind,p,order:skills.length,objective:`Practice ${title.toLowerCase()} with a model, then solve a fresh example.`,teach:teaching[kind]||'Look carefully. Try one step at a time, and explain how you know.',prerequisite:previous?.id});}); }
const teaching:Record<string,string>={count:'Touch or point to each object once. The last number tells how many.',add:'Join the two quantities. Count on, or make a ten. The sum tells how many altogether.',sub:'Start with the whole amount. Take away the smaller amount and count what remains.',missing:'Use the whole and the part you know to find the missing part.',compare:'Compare the greatest place first. If it matches, compare the next place.',sequence:'Find the step between numbers. Use the same step each time.',place:'Each ten is ten ones. Each hundred is ten tens. Build the number one place at a time.',time:'The short hand tells the hour. Count minutes around the clock with the long hand.',money:'Name each coin and its value. Add the values, not just the number of coins.',length:'Line up the start at zero. Count equal units without gaps.',shape:'Look at sides, corners and flat or curved faces to describe the shape.',fraction:'The whole must be divided into equal parts. Count the parts chosen and all equal parts.',data:'Read the labels and the scale. Then compare the amounts.',multiply:'Make equal groups. Count the groups and how many are in each group.',divide:'Start with the whole. Share equally, or find how many equal groups you can make.',area:'Cover the rectangle with equal unit squares. Rows times columns gives its area.',perimeter:'Walk around the outside. Add every side length.',round:'Find the two nearest tens or hundreds. Which one is closer?',word:'Think about the quantities and what happens in the story. Show it with objects or an equation.',odd:'Pair the objects. Even numbers have no object left over; odd numbers have one.',phonics:'Look at the letters. Blend their sounds, then read the whole word.',spelling:'Say the word, listen to its sounds, and put the spelling tiles in order.',syllable:'Listen for each vowel sound. Each syllable has a vowel sound.',morph:'Look at the base word and the beginning or ending added to it.',vocab:'Use the sentence to understand the word, then choose the meaning that fits.',grammar:'Read the whole sentence. Choose the word or mark that makes it clear.',comprehension:'Read the passage. Find words in the passage that support your answer.',fluency:'Read carefully first. Then read again smoothly, with expression and pauses.'};
