const patternTeaching:Record<string,string>={shortA:'The short a sound is in cat and map. Blend from left to right.',shortI:'The short i sound is in sit and pin. Blend each sound.',shortO:'The short o sound is in hot and pot. Keep the sounds in order.',shortU:'The short u sound is in sun and cup. Blend from left to right.',shortE:'The short e sound is in hen and bed. Read each spelling carefully.',digraph:'Two letters can spell one sound. In ship, sh works together. In chin, ch works together.',blend:'A consonant blend keeps both sounds. In frog, listen to f and r at the beginning.',silentE:'A final silent e often changes the earlier vowel to its long sound. Compare cap with cape.',ee:'The vowel team ee spells the long e sound in seed, feet and tree.',ai:'The vowel team ai spells the long a sound in rain and train.',oa:'The vowel team oa spells the long o sound in boat and coat.',r:'The letter r can change the vowel sound before it. Look for ar, er, ir, or and ur.',diphthong:'Look for the vowel patterns oi in coin and ou in cloud. Listen to the word and read the whole pattern.',two:'Find the vowel sounds. Read one syllable, then the next, and join the parts.',three:'A longer word can have three syllables. Read each part, then blend the whole word.',ending:'Find the base word. The ending ed can show a past action; ing can show an ongoing action.',prefix:'A prefix goes before a base word. un can mean not; re can mean again.',suffix:'A suffix follows a base word. ful means full of; less means without; ness names a state or quality.',compound:'A compound word joins two smaller words. Read both parts, then join their meanings.',irregular:'Read the regular parts of the word, then remember the unexpected spelling.'};
for(const s of skills){if(s.subject==='reading'&&patternTeaching[s.p.bank])s.teach=patternTeaching[s.p.bank];if(s.kind==='comprehension'&&s.p.focus==='inference')s.teach='Use clues from the text and what you know. Choose a conclusion the passage supports.';if(s.kind==='comprehension'&&s.p.focus==='main')s.teach='Ask what the whole passage is mostly about. Details should support that main idea.';if(s.kind==='vocab')s.teach=s.p.mode==='opposite'?'An antonym has the opposite meaning. Look for a word that reverses the idea.':'Read the sentence around the word. Nearby details can help you work out its meaning.';}

const extraWords:Record<string,string[]>={shortA:['rag','mat','pan','man','lap','wag','van','ram'],shortI:['tin','bin','dip','kid','rip','mix','six','sip'],shortO:['rod','mop','job','not','sob','fog','cob','pop','cot','lot'],shortU:['tub','rug','hug','gum','nut','bun','dug','sum','pup','hut'],shortE:['men','leg','beg','get','fed','led','met','set'],digraph:['shed','shin','math','path','dish','much','this','that'],blend:['plan','grin','step','flat','slam','plug','skip','trap','glad','spot'],silentE:['late','game','line','time','rude','tube','note','hope','sale','wave'],ee:['bee','see','deep','meet','need','feed','seen','teen','beep','peel'],ai:['mail','sail','fail','nail','paid','laid','rail','main','gain','pain'],oa:['load','oak','soak','toad','moan','coast','roast','goal','loaf','foam','boast','toast'],r:['bark','card','harm','car','horn','cord','dirt','firm','stir','fur','hurt','burn'],diphthong:['oil','foil','toil','point','loud','proud','shout','sound','brown','down'],two:['paper','winter','summer','window','garden','rocket','lesson','pencil','table','pocket'],three:['umbrella','butterfly','dinosaur','computer','newspaper','potato','tornado','spaghetti','remember','magazine','astronaut','together','lemonade'],ending:['walking','walked','playing','played','painting','painted','working','worked','resting','rested','cooking','cooked'],prefix:['unkind','unpaid','undo','unlock','remake','refill','retell','redo','unpack','unsafe','untold','reuse'],suffix:['hopeful','joyful','useful','thankful','playful','colorful','hopeless','helpless','harmless','endless','softness','darkness'],compound:['daytime','bedtime','cupcake','bookshelf','footprint','toothbrush','rainbow','mailbox','football','doorbell','notebook','lunchbox'],irregular:['there','where','their','what','was','once','done','who','could','would','should']};
