storyBank.push(...MORE_STORIES);
const vocabulary=[['tiny','small','large'],['quick','fast','slow'],['joyful','happy','sad'],['silent','quiet','noisy'],['begin','start','finish'],['brave','courageous','afraid'],['bright','shiny','dim'],['simple','easy','difficult'],['warm','mildly hot','cold'],['neat','tidy','messy']];
function syllables(word:string){return phonics.three.includes(word)?3:2;}
function segments(word:string){return word.match(/sh|ch|th|ee|ai|oa|[a-z]/g)||[word];}
function makeBaseQuestion(skill:Skill,seed:number):Question {
 const random=rng(seed);if(skill.kind==='mathStudio')return mathStudioQuestion(skill,seed,random);if(skill.p.studio)return readingStudioQuestion(skill,seed,random);if(skill.kind==='mathDepth')return depthQuestion(skill,seed,random);if(skill.p.mode&&['listening','readingDepth'].includes(skill.kind)||skill.p.mode?.startsWith('book'))return readingDepthQuestion(skill,seed,random);const int=(a:number,b:number)=>a+Math.floor(random()*(b-a+1));const pick=<T,>(items:T[])=>items[int(0,items.length-1)];
 const q:Question={id:`${skill.id}:${seed}`,prompt:'',answer:'',choices:[],hint:skill.teach,explanation:'',};let variants:string[]=[];const p=skill.p;
 const numeric=(n:number)=>{q.answer=String(n);variants=[String(n+1),String(Math.max(0,n-1)),String(n+2),String(n+10),String(Math.max(0,n-10))];};
 const max=p.max||20;let a=int(1,max),b=int(1,max);const k=skill.kind;
 if(skill.subject==='math'){
 if(k==='count'){a=int(1,max);q.prompt='How many counters are on the work mat?';numeric(a);q.visual={type:'counters',count:a};q.explanation=`Count each counter once. There are ${a} counters.`;}
 if(k==='add'||k==='sub'){if(p.tens){a=int(10,max-10);b=int(1,Math.floor((max-a)/10))*10;}else{a=int(1,max-1);b=int(1,max-a);}if(p.regroup){a=int(2,6)*10+int(6,9);b=int(1,2)*10+int(4,8);}
 if(k==='sub'){const whole=a+b;q.prompt=`What is ${whole} − ${b}?`;numeric(a);q.visual={type:'blocks',number:whole,remove:b};q.explanation=`Start with ${whole}. Take away ${b}. ${a} remains.`;}else{q.prompt=`What is ${a} + ${b}?`;numeric(a+b);q.visual={type:'blocks',number:a,other:b};q.explanation=`${a} and ${b} together make ${a+b}.`;} }
 if(k==='missing'){const whole=p.whole||int(3,max);const part=int(1,whole-1);q.prompt=random()>.5?`${part} + ___ = ${whole}. What is missing?`:`___ + ${part} = ${whole}. What is missing?`;numeric(whole-part);q.visual={type:p.whole===10?'tenframe':'counters',count:part,capacity:whole};q.explanation=`${whole} is the whole. ${whole} − ${part} = ${whole-part}.`;}
 if(k==='compare'){a=int(1,max);b=int(1,max);while(b===a)b=int(1,max);q.prompt=`Which is greater: ${a}${p.unit?' '+p.unit:''} or ${b}${p.unit?' '+p.unit:''}?`;q.answer=String(Math.max(a,b));variants=[String(Math.min(a,b)),'They are equal'];q.explanation=`${Math.max(a,b)} is greater than ${Math.min(a,b)}.`;}
 if(k==='sequence'){const step=p.step||1;a=int(0,Math.max(0,Math.floor(max/step)-3))*step;q.prompt=`${a}, ${a+step}, ${a+step*2}, ___ . What comes next?`;numeric(a+step*3);q.explanation=`Add ${step} each time. The next number is ${a+step*3}.`;}
 if(k==='place'){a=int(p.max>99?100:10,p.max);const hundreds=Math.floor(a/100),tens=Math.floor(a/10)%10,ones=a%10;q.visual={type:'blocks',number:a};if(p.ask==='number'){q.prompt='What number do these blocks represent?';numeric(a);}else{q.prompt=`How many ${p.ask} are in ${a}?`;numeric(p.ask==='hundreds'?hundreds:tens);}q.explanation=`${a} has ${hundreds?hundreds+' hundreds, ':''}${tens} tens and ${ones} ones.`;}
 if(k==='multiply'||k==='divide'||k==='area'){a=p.factor||pick(p.factors||Array.from({length:p.max||5},(_,i)=>i+1));b=int(1,p.max||5);const total=a*b;q.visual={type:'array',rows:a,cols:b,unitSquares:k==='area'};if(k==='divide'){q.prompt=p.ask==='groups'?`${total} counters go in groups of ${b}. How many groups?`:`Share ${total} counters equally into ${a} groups. How many in each group?`;numeric(p.ask==='groups'?a:b);q.explanation=`${a} groups of ${b} make ${total}, so ${total} ÷ ${p.ask==='groups'?b:a} = ${p.ask==='groups'?a:b}.`;}else{q.prompt=k==='area'?`A rectangle has ${a} rows of ${b} unit squares. What is its area?`:`${a} equal groups of ${b}. How many altogether?`;numeric(total);q.explanation=skill.grade===2?`${Array.from({length:a},()=>b).join(' + ')} = ${total}. Add each equal row once.`:`${a} × ${b} = ${total}${k==='area'?' square units':''}.`;}}
 if(k==='fraction'){const d=pick<number>(p.denoms),n=p.unit?1:int(1,d-1);q.visual={type:'fraction',parts:d,filled:n,line:!!p.line};q.prompt=p.line?'Which fraction names the gold point on the number line?':'What fraction of the whole is highlighted?';q.answer=`${n}/${d}`;variants=[`${d}/${n}`,`${n}/${d+1}`,`${Math.min(d,n+1)}/${d}`,`${Math.max(0,n-1)}/${d}`];q.explanation=`${n} of the ${d} equal parts are highlighted: ${n}/${d}.`;if(p.equivalent){q.prompt=`Which fraction equals ${n}/${d}?`;q.answer=`${n*2}/${d*2}`;variants=[`${n}/${d*2}`,`${n*2}/${d}`,`${n+1}/${d+1}`];q.explanation=`Divide each part in two. ${n}/${d} and ${n*2}/${d*2} name the same amount.`;}if(p.compare){const m=n<d-1?n+1:n-1;q.prompt=`Which is greater: ${n}/${d} or ${m}/${d}?`;q.answer=`${Math.max(n,m)}/${d}`;variants=[`${Math.min(n,m)}/${d}`,'They are equal'];q.explanation='With the same-sized whole and denominator, more equal parts means a greater fraction.';}}
 if(k==='fraction'&&skill.grade<3){const {parts,filled}=q.visual,words=['Zero','One','Two','Three','Four'],names:Record<number,string>={2:'half',3:'third',4:'fourth'};const label=(n:number,d:number)=>`${words[n]} ${names[d]}${n===1?'':d===2?'ves':'s'}`.replace('halfves','halves');q.answer=label(filled,parts);variants=[label(filled,parts===2?4:2),label(filled+1,parts)];q.prompt='The whole has equal shares. What do we call the selected shares?';q.explanation=`${parts} equal shares make this whole. ${filled} are selected: ${q.answer.toLowerCase()}.`;q.visual.simpleShare=true;}
 if(k==='time'){const hour=int(1,12),minute=p.step===60?0:int(0,Math.floor(59/p.step))*p.step;q.visual={type:'clock',hour,minute};q.prompt='What time does the clock show?';q.answer=`${hour}:${String(minute).padStart(2,'0')}`;variants=[`${hour%12+1}:${String(minute).padStart(2,'0')}`,`${hour}:${String((minute+30)%60).padStart(2,'0')}`,`${hour}:${String((minute+5)%60).padStart(2,'0')}`];q.explanation=`The short hand shows the hour, ${hour}. The long hand shows ${minute} minutes.`;if(p.elapsed){const minutes=pick([5,10,15,20,30]);q.prompt=`Start at ${q.answer}. What time is it ${minutes} minutes later?`;const end=(hour%12)*60+minute+minutes;q.answer=`${Math.floor(end/60)%12||12}:${String(end%60).padStart(2,'0')}`;variants=[`${hour}:${String(minute).padStart(2,'0')}`,`${Math.floor(end/60)%12||12}:${String((end+5)%60).padStart(2,'0')}`];q.explanation=`Move ${minutes} minutes forward on the clock to ${q.answer}.`;}}
 if(k==='money'){const cents=[1,5,10,25];const coins=Array.from({length:int(2,p.max||5)},()=>pick(cents));const total=coins.reduce((n,c)=>n+c,0);q.prompt='How many cents are these coins worth altogether?';numeric(total);q.visual={type:'coins',coins};q.explanation=`Add each coin's value: ${coins.join(' + ')} = ${total} cents.`;}
 if(k==='length'){a=int(2,max);q.prompt='The measuring strip begins at 0. How many units long is it?';numeric(a);q.visual={type:'ruler',length:a};q.explanation=`Count ${a} equal units from 0 to ${a}.`;}
 if(k==='shape'){const shapes=[{name:'Triangle',sides:3},{name:'Square',sides:4},{name:'Rectangle',sides:4},{name:'Pentagon',sides:5},{name:'Hexagon',sides:6}];const shape=pick(shapes);q.visual={type:'shape',...shape};if(p.mode==='sides'){q.prompt=`How many sides does a ${shape.name.toLowerCase()} have?`;numeric(shape.sides);}else{q.prompt=`Which is the most specific name for the shape with ${shape.sides} sides${shape.name==='Square'?', four equal sides and four right angles':shape.name==='Rectangle'?', four right angles and two longer sides':''}?`;q.answer=shape.name;variants=shapes.map(s=>s.name).filter(n=>n!==q.answer);if(shape.name==='Rectangle')variants=variants.filter(n=>n!=='Square');}q.explanation=`A ${shape.name.toLowerCase()} has ${shape.sides} straight sides.`;}
 if(k==='quad'){const [name,attribute]=pick([['Square','four equal sides and four right angles'],['Rectangle','four right angles with two long sides and two short sides'],['Rhombus','four equal sides with no right angles'],['Trapezoid','exactly one pair of parallel sides and unequal side lengths']]);q.prompt=`Which is the most specific name among these choices for a quadrilateral with ${attribute}?`;q.answer=name;variants=['Square','Rectangle','Rhombus','Trapezoid'].filter(w=>w!==name);q.explanation=`This ${name.toLowerCase()} is a quadrilateral: it has four straight sides. Its defining clue is ${attribute}.${name==='Square'?' A square is also a rectangle and a rhombus; square is its most specific name here.':''}`;q.hint='A quadrilateral has four sides. Compare equal sides, parallel sides and right angles.';}
 if(k==='data'){const scale=p.scale||1;a=int(1,Math.floor(max/scale))*scale;b=int(1,Math.floor(max/scale))*scale;const c=int(1,Math.floor(max/scale))*scale;q.visual={type:'chart',values:[a,b,c],labels:['Blue','Gold','Coral'],scale};q.prompt=p.compare?a===b?'Blue and Gold have the same amount. What is the difference?':`How many more blocks does ${a>b?'Blue':'Gold'} have than ${a>b?'Gold':'Blue'}?`:scale>1?`Each symbol represents ${scale} votes. How many Blue votes are represented?`:'How many blue blocks are represented?';numeric(p.compare?Math.abs(a-b):a);q.explanation=p.compare?`Find the difference: ${Math.max(a,b)} − ${Math.min(a,b)} = ${Math.abs(a-b)}.`:scale>1?`${a/scale} symbols × ${scale} votes per symbol = ${a} votes.`:`Read the blue amount: ${a}.`;}
 if(k==='perimeter'){a=int(2,max);b=int(2,max);q.prompt=`A rectangle is ${a} units long and ${b} units wide. What is its perimeter?`;numeric(2*(a+b));q.visual={type:'rectangle',length:a,width:b};q.explanation=`Add all four sides: ${a} + ${b} + ${a} + ${b} = ${2*(a+b)} units.`;}
 if(k==='round'){const step=p.step;a=int(1,max);const rounded=Math.round(a/step)*step;q.prompt=`Round ${a} to the nearest ${step===10?'ten':'hundred'}.`;numeric(rounded);variants=[String(Math.floor(a/step)*step),String(Math.ceil(a/step)*step),String(rounded+step),String(Math.max(0,rounded-step))];q.explanation=`Compare ${Math.floor(a/step)*step} and ${Math.ceil(a/step)*step}. ${a} rounds to ${rounded}.`;}
 if(k==='odd'){a=int(1,max);q.prompt=`Is ${a} odd or even?`;q.answer=a%2?'Odd':'Even';variants=[a%2?'Even':'Odd'];q.visual={type:'counters',count:a};q.explanation=a%2?'Pair the counters. One remains, so the number is odd.':'All counters can be paired, so the number is even.';}
 if(k==='word'){const name=pick(p.op==='difference'?['Mia','Sam','Lena','Omar']:['Mia','Theo','Sam','Lena','Omar']),items=p.unit||pick(['blocks','seeds','books','shells']);a=int(2,Math.max(3,max-1));b=int(1,Math.max(1,max-a));if(p.op==='multiply'||p.op==='divide'){a=int(2,8);b=int(2,8);q.prompt=p.op==='multiply'?`${name} fills ${a} boxes with ${b} ${items} in each box. How many ${items} altogether?`:`${name} shares ${a*b} ${items} equally into ${a} boxes. How many in each box?`;numeric(p.op==='multiply'?a*b:b);q.visual={type:'array',rows:a,cols:b};q.explanation=p.op==='multiply'?`${a} equal groups of ${b} make ${a*b}.`:`${a*b} ÷ ${a} = ${b}.`;}else if(p.op==='sub'){q.prompt=`${name} has ${a+b} ${items} and gives away ${b}. How many remain?`;numeric(a);q.explanation=`${a+b} − ${b} = ${a}.`;}else if(p.op==='difference'){q.prompt=`${name} has ${a+b} ${items}. Theo has ${b}. How many more does ${name} have?`;numeric(a);q.explanation=`Compare the amounts: ${a+b} − ${b} = ${a}.`;}else if(p.op==='two'){const c=int(1,a+b-1);q.prompt=`${name} starts with ${a} ${items}, gets ${b} more, then gives away ${c}. How many remain?`;numeric(a+b-c);q.explanation=`First ${a} + ${b} = ${a+b}. Then ${a+b} − ${c} = ${a+b-c}.`;}else{q.prompt=`${name} has ${a} ${items} and gets ${b} more. How many altogether?`;numeric(a+b);q.explanation=`${a} + ${b} = ${a+b}.`;}}
 }else{
 const bank=phonics[p.bank||'shortA'];const word=pick(bank);if(['phonics','spelling','syllable','morph'].includes(k))q.word=word;
 if(k==='phonics'){q.prompt='Listen to the word, then choose its spelling.';q.answer=word;variants=bank.filter(w=>w!==word&&!(['there','their'].includes(word)&&['there','their'].includes(w)));q.hint='Look at each choice and blend its sounds from left to right.';q.explanation=`The word is ${word}. Try reading another word with the same pattern.`;}
 if(k==='spelling'){q.prompt='Listen to the word, then build its spelling.';q.answer=word;q.tiles=segments(word);q.passage=undefined;q.hint=`Say ${word} slowly. Put its spelling tiles in sound order.`;q.explanation=`${segments(word).join(' · ')} spells ${word}.`;variants=bank.filter(w=>w!==word);}
 if(k==='syllable'){q.prompt=`How many syllables are in “${word}”?`;numeric(syllables(word));q.passage=word;q.explanation=`${word} has ${syllables(word)} syllables. Listen for its vowel sounds.`;}
 if(k==='morph'){q.passage=word;if(p.bank==='prefix'){const prefix=word.startsWith('un')?'un':'re';q.prompt=`In “${word}”, what does ${prefix}- mean?`;q.answer=prefix==='un'?'Not or the opposite':'Again';variants=['A person who does it','Full of','Without'];q.explanation=`${prefix}- means ${q.answer.toLowerCase()}.`;}else if(p.bank==='suffix'){q.prompt=`What does the ending in “${word}” mean?`;q.answer=word.endsWith('ful')?'Full of':word.endsWith('less')?'Without':'A state or quality';variants=['Again','Not or the opposite','An action happening now'];q.explanation=`The suffix changes the base word's meaning: ${q.answer.toLowerCase()}.`;}else if(p.bank==='compound'){const map:Record<string,string>={sunshine:'sun + shine',raincoat:'rain + coat',bedroom:'bed + room',playground:'play + ground',backpack:'back + pack',snowman:'snow + man',daytime:'day + time',bedtime:'bed + time',cupcake:'cup + cake',bookshelf:'book + shelf',footprint:'foot + print',toothbrush:'tooth + brush',rainbow:'rain + bow',mailbox:'mail + box',football:'foot + ball',doorbell:'door + bell',notebook:'note + book',lunchbox:'lunch + box'};q.prompt=`Which two words make “${word}”?`;q.answer=map[word];variants=['sun + room','rain + man','bed + shine'];q.explanation=`${q.answer} makes ${word}.`;}else{q.prompt=`What is the base word in “${word}”?`;q.answer=word.replace(/ing$|ed$/,'');variants=['jump','help','look'].filter(w=>w!==q.answer);q.explanation=`Start with ${q.answer}, then add the ending.`;}}
 if(k==='vocab'){const v=pick(vocabulary);q.prompt=p.mode==='opposite'?`Which word means the opposite of “${v[0]}”?`:`Which meaning fits “${v[0]}” in this sentence?`;const contexts:Record<string,string>={tiny:'The tiny insect was smaller than a grain of rice.',quick:'The quick runner reached the finish line before everyone else.',joyful:'Lena felt joyful and smiled all the way home.',silent:'The room was silent. Nobody spoke or made a sound.',begin:'We begin the lesson by opening the first page.',brave:'The brave child tried the tall slide even though it felt scary.',bright:'The bright lamp lit every corner of the room.',simple:'The simple puzzle was easy for Theo to solve.',warm:'The warm scarf helped Mia feel comfortable on a cool day.',neat:'The neat desk had every pencil in its own place.'};q.passage=p.mode==='opposite'?undefined:contexts[v[0]];q.answer=p.mode==='opposite'?v[2]:v[1];variants=[p.mode==='opposite'?v[1]:v[2],'A number','A place'];q.explanation=`${v[0]} means ${v[1]}. Its opposite is ${v[2]}.`;}
 if(k==='grammar'){const examples:Record<string,any[]>={noun:[['The dog runs beside Mia.','Which word names an animal?','dog',['runs','beside','the']],['Lena reads a book.','Which word names a thing?','book',['reads','a','quickly']]],verb:[['The rabbit hops over the log.','Which word shows an action?','hops',['rabbit','log','the']],['Omar paints a picture.','Which word shows the action?','paints',['Omar','picture','a']]],adjective:[['Mia carries a heavy bag.','Which word describes the bag?','heavy',['carries','Mia','bag']],['Theo sees a bright star.','Which word describes the star?','bright',['sees','Theo','star']]],capital:[['___ has a red hat.','Which spelling begins the sentence correctly?','Sam',['sam','sAm','saM']]],punctuation:[['Where is my book___','Which mark ends this question?','?',['.','!',',']],['I have a blue pen___','Which mark ends this statement?','.',['?',',',':']]],pronoun:[['Mia has a kite. ___ flies it.','Which pronoun can replace Mia?','She',['It','They','We']]],past:[['Yesterday, Theo ___ to the park.','Which verb shows the past?','walked',['walks','walking','walk']]]};const names=['Sam','Mia','Ben','Lena','Omar','Nina','Kai','Ava','Jun','Rosa','Max','Zoe','Lee','Theo','Nora'];if(p.mode==='capital')examples.capital=names.map(n=>['___ has a red hat.','Which spelling begins the sentence correctly?',n,[n.toLowerCase(),n.toUpperCase().slice(0,1).toLowerCase()+n.slice(1).toUpperCase(),n.toLowerCase().slice(0,-1)+n.at(-1)!.toUpperCase()]]);if(p.mode==='verb')examples.verb=[['runs','dog'],['jumps','cat'],['flies','bird'],['swims','fish'],['reads','child'],['claps','bear'],['paints','artist'],['dances','friend'],['writes','teacher'],['cooks','parent']].map(([verb,noun])=>[`The ${noun} ${verb} near Theo.`,`Which word shows an action?`,verb,[noun,'near','The']]);if(p.mode==='adjective')examples.adjective=[['small','box'],['big','ball'],['soft','scarf'],['bright','star'],['long','rope'],['tall','tree'],['heavy','bag'],['round','plate'],['blue','pen'],['quiet','room']].map(([adjective,noun])=>[`Mia sees a ${adjective} ${noun}.`,`Which word describes the ${noun}?`,adjective,['Mia','sees',noun]]);if(p.mode==='punctuation')examples.punctuation=names.flatMap(n=>[[`Where is ${n}'s book___`,'Which mark ends this question?','?',['.','!',',']],[`${n} has a blue pen___`,'Which mark ends this statement?','.',['?',',',':']]]);if(p.mode==='noun')examples.noun=['book','pencil','ball','bag','cup','plate','hat','kite','rope','box'].map(n=>[`Theo carries a ${n}.`,'Which word names a thing?',n,['carries','a','quickly']]);if(p.mode==='past')examples.past=[['walk','walked','walks','walking','to the park'],['play','played','plays','playing','a game'],['jump','jumped','jumps','jumping','over a log'],['look','looked','looks','looking','at a map'],['help','helped','helps','helping','a friend'],['paint','painted','paints','painting','a picture'],['work','worked','works','working','in the garden'],['rest','rested','rests','resting','on a bench'],['cook','cooked','cooks','cooking','a meal'],['talk','talked','talks','talking','with Theo'],['run','ran','runs','running','around the field'],['go','went','goes','going','home'],['eat','ate','eats','eating','an apple'],['see','saw','sees','seeing','a rainbow']].map(([base,past,present,ongoing,tail],i)=>[`Yesterday, ${names[i]} ___ ${tail}.`,'Which verb shows the past?',past,[present,ongoing,base]]);if(p.mode==='pronoun')examples.pronoun=[['The girls have new kites. ___ fly them.','They'],['The boys wash a car. ___ use soap.','They'],['Mia and I have a book. ___ read together.','We'],['The robot lifts a box. ___ carries it.','It'],['The girl likes science. ___ reads about stars.','She'],['The boy paints a card. ___ gives it to a friend.','He'],['The birds build nests. ___ collect twigs.','They'],['Theo and I like stories. ___ read every day.','We'],['A girl carries a basket. ___ puts it down.','She'],['A boy has a kite. ___ holds its string.','He'],['The plant has a flower. ___ grows by the window.','It'],['The parents carry bags. ___ set them on the table.','They']].map(([sentence,correct])=>[sentence,'Which pronoun fits the sentence?',correct,['He','She','It','We','They'].filter(w=>w!==correct)]);const e=pick(examples[p.mode]||examples.noun);q.passage=e[0];q.prompt=e[1];q.answer=e[2];variants=e[3];q.explanation=`“${q.answer}” fits the sentence and the question.`;}
 if(k==='comprehension'||k==='fluency'){const pool=storyBank.filter(s=>s.grade===skill.grade),story=pick(pool);q.passage=story.text;const focus=k==='fluency'?'detail':p.focus||'detail';const field=(focus==='sequence'?'first':focus) as keyof typeof story;if(typeof story[field]!=='string')throw new Error(`Invalid story focus: ${focus}`);const prompts:Record<string,string>={character:'Who or what is the passage mainly about?',setting:'Where does the passage happen?',sequence:'What happens first?',detail:'Which detail appears in the passage?',main:'Which sentence best tells what the passage is about?',cause:'Which reason fits what happened?',inference:'What can you reasonably infer from the passage?',fact:'Which statement is supported by the passage?'};q.prompt=k==='fluency'?'Read the passage smoothly, then choose a detail you read.':prompts[focus];q.answer=focus==='sequence'?story.text.split(/(?<=[.!?])\s+/)[0]:String(story[field]);variants=pool.filter(s=>s!==story).map(s=>focus==='sequence'?s.text.split(/(?<=[.!?])\s+/)[0]:String(s[field]));q.explanation=`The passage supports “${q.answer}”. Point to the words that helped you.`;q.hint='Reread the passage and find the matching words. Take your time.';}
 }
 if(!q.prompt||!q.answer)throw new Error(`Missing generator for ${skill.id} ${k}`);
 const unique=[...new Set([q.answer,...variants])];if(unique.length<2)unique.push('Try another amount');const count=['compare','odd','fraction'].includes(k)?Math.min(4,unique.length):Math.min(4,unique.length);
 const distractors=unique.filter(v=>v!==q.answer).sort(()=>random()-.5).slice(0,count-1);q.choices=[q.answer,...distractors];for(let i=q.choices.length-1;i>0;i--){const j=int(0,i);[q.choices[i],q.choices[j]]=[q.choices[j],q.choices[i]];}
 return q;
}

export function questionFingerprint(q:Question){return JSON.stringify([q.prompt,q.passage,q.word,q.answer,q.visual,q.listeningText,q.tiles]);}
// Compact content identity lets later sessions recognize a practiced item.
// This is an evidence key, not a security hash or a learner identifier.
export function questionContentId(q:Question){if(q.canonicalContentId)return q.canonicalContentId;let hash=0xcbf29ce484222325n;for(const char of questionFingerprint(q)){hash^=BigInt(char.codePointAt(0)!);hash=BigInt.asUintN(64,hash*0x100000001b3n);}return hash.toString(16).padStart(16,'0');}
export function makeQuestion(skill:Skill,seed:number):Question{
 if(skill.p.language==='es')return {...spanishQuestion(skill,seed),language:'es'};
 const base=makeBaseQuestion(skill,seed);if(skill.subject!=='math'||(skill.language||getLocale())!=='es')return base;
 const translated={...base,canonicalKey:questionKey(base),canonicalContentId:questionContentId(base),language:'es' as const};
 for(const key of ['prompt','answer','hint','explanation','passage','word','listeningText'] as const){const value=base[key];if(value)(translated as any)[key]=translateText(value,'es',0,false);}translated.choices=base.choices.map(c=>translateText(c,'es',0,false));if(base.visual?.labels)translated.visual={...base.visual,labels:base.visual.labels.map((s:string)=>translateText(s,'es',0,false))};return translated;
}
export function freshQuestion(skill:Skill,seed:number,index:number){const seen=new Set([questionFingerprint(makeQuestion(skill,seed+913))]);let q=makeQuestion(skill,seed);for(let i=0;i<=index;i++){for(let attempt=0;attempt<80;attempt++){q=makeQuestion(skill,seed+i*7919+attempt*101);if(!seen.has(questionFingerprint(q)))break;}q.repeated=seen.has(questionFingerprint(q));seen.add(questionFingerprint(q));}return q;}
